export function computeRepositoryHash(parsedFiles: ParsedFile[]): string {
  const hash = crypto.createHash("sha256");

  // Sort by filePath for deterministic hash order
  const sorted = [...parsedFiles].sort((a, b) =>
    a.filePath.localeCompare(b.filePath),
  );

  for (const file of sorted) {
    hash.update(file.filePath);
    hash.update(file.content);
  }

  return hash.digest("hex");
}

export async function loadGraphCache(
  cachePath: string = DEFAULT_CACHE_PATH,
): Promise<GraphCacheData | null> {
  try {
    const raw = await fs.readFile(cachePath, "utf-8");
    const data = JSON.parse(raw) as GraphCacheData;

    if (data.version !== CACHE_VERSION) {
      return null;
    }

    return data;
  } catch {
    return null;
  }
}

export async function testDatabaseConnection(): Promise<boolean> {
  try {
    const health = await getDatabaseHealth();
    if (health.status === "healthy") {
      console.log(`✓ PostgreSQL connected (Latency: ${health.latencyMs}ms, Pool: ${health.totalConnections} active).`);
      return true;
    }
    console.error("❌ PostgreSQL health check failed.");
    return false;
  } catch (error) {
    console.error("❌ PostgreSQL connection failed:", error);
    return false;
  }
}

export async function setHnswSearchPrecision(efSearch = 100): Promise<void> {
  await query(`SET LOCAL hnsw.ef_search = ${Math.floor(efSearch)};`);
}

export async function rebuildHnswIndex(
  options: HnswTuningOptions = {},
): Promise<void> {
  const m = options.m ?? 16;
  const efConstruction = options.efConstruction ?? 64;

  console.log(`⚙ Tuning HNSW index parameters (m=${m}, ef_construction=${efConstruction})...`);

  await query(`DROP INDEX IF EXISTS idx_code_chunks_embedding_hnsw;`);

  await query(`
    CREATE INDEX idx_code_chunks_embedding_hnsw
    ON code_chunks
    USING hnsw (embedding vector_cosine_ops)
    WITH (m = ${m}, ef_construction = ${efConstruction});
  `);

  console.log("✓ HNSW index successfully tuned and rebuilt.");
}

public recordRetrieval(
    totalMs: number,
    vectorMs: number,
    graphMs: number,
    rerankMs: number,
    success = true,
  ): void {
    this.retrievalRequests++;
    if (!success) {
      this.failedRetrievals++;
    }
    this.totalRetrievalLatencyMs += totalMs;
    this.totalVectorLatencyMs += vectorMs;
    this.totalGraphLatencyMs += graphMs;
    this.totalRerankLatencyMs += rerankMs;
  }

public recordDbQuery(success = true): void {
    this.dbQueries++;
    if (!success) {
      this.failedDbQueries++;
    }
  }

public recordCacheHit(hit: boolean): void {
    if (hit) {
      this.cacheHits++;
    } else {
      this.cacheMisses++;
    }
  }

public recordIndexing(indexed: number, deleted: number, durationMs: number): void {
    this.indexedFiles += indexed;
    this.deletedFiles += deleted;
    this.lastIndexingDurationMs = durationMs;
  }

