function createFileEntity(file: ParsedFile): GraphEntity {
  return {
    id: `file:${normalizeId(file.filePath)}`,

    type: "file",

    name: path.basename(file.filePath),

    filePath: file.filePath,

    startLine: 1,

    endLine: file.content
      ? file.content.split(/\r?\n/).length
      : 1,

    language: file.language,

    metadata: {
      directory: path.dirname(file.filePath),
      imports: file.imports.map((item) => item.source),
    },
  };
}

function createFunctionEntity(
  file: ParsedFile,
  fn: ParsedFunction,
): GraphEntity {
  return {
    id: `function:${normalizeId(file.filePath)}:${normalizeId(fn.name)}:${fn.startLine}`,

    type: "function",

    name: fn.name,

    filePath: file.filePath,

    startLine: fn.startLine,
    endLine: fn.endLine,

    language: file.language,

    metadata: {
      parentFile: file.filePath,
    },
  };
}

function createModuleEntities(
  file: ParsedFile,
): GraphEntity[] {
  const modules: GraphEntity[] = [];

  for (const importedModule of file.imports) {
    modules.push({
      id: `module:${normalizeId(importedModule.source)}`,

      type: "module",

      name: importedModule.source,

      metadata: {
        importedBy: file.filePath,
      },
    });
  }

  return modules;
}

export function extractEntitiesFromFile(
  file: ParsedFile,
): GraphEntity[] {
  const entities: GraphEntity[] = [];

  entities.push(createFileEntity(file));

  for (const fn of file.functions) {
    entities.push(createFunctionEntity(file, fn));
  }

  for (const classInfo of file.classes) {
    entities.push(createClassEntity(file, classInfo));
  }

  entities.push(...createModuleEntities(file));

  return entities;
}

export function extractEntities(
  parsedFiles: ParsedFile[],
): GraphEntity[] {
  const entityMap = new Map<string, GraphEntity>();

  for (const file of parsedFiles) {
    const entities = extractEntitiesFromFile(file);

    for (const entity of entities) {
      if (!entityMap.has(entity.id)) {
        entityMap.set(entity.id, entity);
      }
    }
  }

  return Array.from(entityMap.values());
}

export function buildGraph(
  entities: GraphEntity[],
  relationships: GraphRelationship[],
): CodeGraph {
  const nodes = new Map<string, GraphEntity>();
  const outgoing = new Map<string, GraphRelationship[]>();
  const incoming = new Map<string, GraphRelationship[]>();

  for (const entity of entities) {
    nodes.set(entity.id, entity);
  }

  for (const relationship of relationships) {
    if (!outgoing.has(relationship.sourceId)) {
      outgoing.set(relationship.sourceId, []);
    }

    if (!incoming.has(relationship.targetId)) {
      incoming.set(relationship.targetId, []);
    }

    outgoing.get(relationship.sourceId)!.push(relationship);
    incoming.get(relationship.targetId)!.push(relationship);
  }

  return {
    nodes,
    edges: relationships,
    outgoing,
    incoming,
  };
}

export function getNode(
  graph: CodeGraph,
  entityId: string,
): GraphEntity | undefined {
  return graph.nodes.get(entityId);
}

export async function initializeSchema(): Promise<void> {
  await runMigrations();
}

export function validateQueryLength(query: string): string {
  if (!query || typeof query !== "string") {
    throw new ResourceLimitError("Query must be a non-empty string.");
  }

  const trimmed = query.trim();

  if (trimmed.length === 0) {
    throw new ResourceLimitError("Query cannot be empty or blank.");
  }

  if (trimmed.length > LIMITS.maxQueryLength) {
    throw new ResourceLimitError(
      `Query length (${trimmed.length} chars) exceeds maximum limit of ${LIMITS.maxQueryLength} characters.`,
    );
  }

  return trimmed;
}

export function getGraphStats(graph: CodeGraph) {
  const entityCounts = new Map<string, number>();
  const relationshipCounts = new Map<string, number>();

  for (const entity of graph.nodes.values()) {
    entityCounts.set(
      entity.type,
      (entityCounts.get(entity.type) ?? 0) + 1,
    );
  }

  for (const edge of graph.edges) {
    relationshipCounts.set(
      edge.type,
      (relationshipCounts.get(edge.type) ?? 0) + 1,
    );
  }

  return {
    totalNodes: graph.nodes.size,
    totalEdges: graph.edges.length,
    entityCounts: Object.fromEntries(entityCounts),
    relationshipCounts: Object.fromEntries(
      relationshipCounts,
    ),
  };
}

function normalizeId(value: string): string {
  return value
    .replace(/\\/g, "/")
    .replace(/[^a-zA-Z0-9/_-]/g, "-")
    .toLowerCase();
}

function createRelationshipId(
  sourceId: string,
  type: RelationshipType,
  targetId: string,
): string {
  return `${sourceId}:${type}:${targetId}`;
}

function createImportRelationships(
  file: ParsedFile,
): GraphRelationship[] {
  const relationships: GraphRelationship[] = [];

  const fileEntityId = `file:${normalizeId(file.filePath)}`;

  for (const importedModule of file.imports) {
    const moduleEntityId =
      `module:${normalizeId(importedModule.source)}`;

    relationships.push({
      id: createRelationshipId(
        fileEntityId,
        "imports",
        moduleEntityId,
      ),

      type: "imports",

      sourceId: fileEntityId,
      targetId: moduleEntityId,

      metadata: {
        source: importedModule.source,
        names: importedModule.names,
        line: importedModule.line,
      },
    });
  }

  return relationships;
}

async function getRetriever(): Promise<CodeRetriever> {
  if (!retriever) {
    retriever = new CodeRetriever(process.cwd());
  }

  if (!initialized) {
    await retriever.initialize();
    initialized = true;
  }

  return retriever;
}

export function findEntitiesByName(
  graph: CodeGraph,
  name: string,
): GraphEntity[] {
  const normalized = name.toLowerCase();

  return Array.from(graph.nodes.values()).filter(
    (entity) =>
      entity.name.toLowerCase() === normalized,
  );
}

function createContainsRelationships(
  file: ParsedFile,
  entities: GraphEntity[],
): GraphRelationship[] {
  const relationships: GraphRelationship[] = [];

  const fileEntityId = `file:${normalizeId(file.filePath)}`;

  const childEntities = entities.filter(
    (entity) =>
      entity.filePath === file.filePath &&
      (
        entity.type === "function" ||
        entity.type === "class"
      ),
  );

  for (const child of childEntities) {
    relationships.push({
      id: createRelationshipId(
        fileEntityId,
        "contains",
        child.id,
      ),

      type: "contains",

      sourceId: fileEntityId,
      targetId: child.id,

      metadata: {
        filePath: file.filePath,
      },
    });
  }

  return relationships;
}

export function getIncoming(
  graph: CodeGraph,
  entityId: string,
  relationshipTypes?: RelationshipType[],
): GraphRelationship[] {
  const edges = graph.incoming.get(entityId) ?? [];

  if (!relationshipTypes || relationshipTypes.length === 0) {
    return edges;
  }

  return edges.filter((edge) =>
    relationshipTypes.includes(edge.type),
  );
}

export async function saveGraphCache(
  data: Omit<GraphCacheData, "version" | "createdAt">,
  cachePath: string = DEFAULT_CACHE_PATH,
): Promise<void> {
  try {
    await fs.mkdir(path.dirname(cachePath), { recursive: true });

    const cachePayload: GraphCacheData = {
      version: CACHE_VERSION,
      repositoryHash: data.repositoryHash,
      createdAt: new Date().toISOString(),
      entities: data.entities,
      relationships: data.relationships,
    };

    await fs.writeFile(
      cachePath,
      JSON.stringify(cachePayload, null, 2),
      "utf-8",
    );
  } catch (error) {
    console.warn("⚠ Failed to save graph cache:", error);
  }
}

function createChunkId(
  filePath: string,
  type: ChunkType,
  name: string,
  startLine: number,
): string {
  const normalizedPath = filePath
    .replace(/\\/g, "/")
    .replace(/[^a-zA-Z0-9/_-]/g, "-");

  const normalizedName = name
    .replace(/[^a-zA-Z0-9_-]/g, "-")
    .toLowerCase();

  return `${normalizedPath}:${type}:${normalizedName}:${startLine}`;
}

function functionToChunk(
  file: ParsedFile,
  fn: ParsedFunction,
): CodeChunk {
  return {
    id: createChunkId(
      file.filePath,
      "function",
      fn.name,
      fn.startLine,
    ),

    type: "function",

    filePath: file.filePath,
    language: file.language,

    name: fn.name,

    startLine: fn.startLine,
    endLine: fn.endLine,

    content: fn.content,

    metadata: createMetadata(file),
  };
}

function fileToChunk(file: ParsedFile): CodeChunk {
  const lineCount = getLineCount(file.content);

  return {
    id: createChunkId(
      file.filePath,
      "file",
      path.basename(file.filePath),
      1,
    ),

    type: "file",

    filePath: file.filePath,
    language: file.language,

    name: path.basename(file.filePath),

    startLine: 1,
    endLine: Math.max(lineCount, 1),

    content: file.content,

    metadata: createMetadata(file),
  };
}

export function extractRelationshipsFromFile(
  file: ParsedFile,
  entities: GraphEntity[],
): GraphRelationship[] {
  return [
    ...createContainsRelationships(
      file,
      entities,
    ),

    ...createImportRelationships(file),

    ...createCallRelationships(
      file,
      entities,
    ),
  ];
}

export function extractRelationships(
  parsedFiles: ParsedFile[],
  entities: GraphEntity[],
): GraphRelationship[] {
  const relationshipMap =
    new Map<string, GraphRelationship>();

  for (const file of parsedFiles) {
    const relationships =
      extractRelationshipsFromFile(
        file,
        entities,
      );

    for (const relationship of relationships) {
      if (!relationshipMap.has(relationship.id)) {
        relationshipMap.set(
          relationship.id,
          relationship,
        );
      }
    }
  }

  return Array.from(
    relationshipMap.values(),
  );
}

function getLineCount(content: string): number {
  if (!content) {
    return 0;
  }

  return content.split(/\r?\n/).length;
}

function createMetadata(file: ParsedFile) {
  return {
    fileName: path.basename(file.filePath),
    directory: path.dirname(file.filePath),
    imports: file.imports.map((item) => item.source),
  };
}

function classToChunk(
  file: ParsedFile,
  classInfo: ParsedClass,
): CodeChunk {
  return {
    id: createChunkId(
      file.filePath,
      "class",
      classInfo.name,
      classInfo.startLine,
    ),

    type: "class",

    filePath: file.filePath,
    language: file.language,

    name: classInfo.name,

    startLine: classInfo.startLine,
    endLine: classInfo.endLine,

    content: classInfo.content,

    metadata: createMetadata(file),
  };
}

function computeContentHash(content: string): string {
  return crypto.createHash("sha256").update(content).digest("hex");
}

