export async function buildVectorIndex(
  chunks: CodeChunk[],
): Promise<VectorDocument[]> {
  const documents: VectorDocument[] = [];

  for (const chunk of chunks) {
    if (!chunk.content.trim()) {
      continue;
    }

    const embedding =
      await embedText(
        [
          `Type: ${chunk.type}`,
          `Name: ${chunk.name ?? ""}`,
          `File: ${chunk.filePath}`,
          "",
          chunk.content,
        ].join("\n"),
      );

    documents.push({
      chunk,
      embedding,
    });
  }

  return documents;
}

