export async function vectorSearch(
  query: string,
  index: VectorDocument[],
  limit = 10,
): Promise<VectorSearchResult[]> {
  const queryEmbedding =
    await embedText(query);

  return index
    .map((document) => ({
      chunk: document.chunk,

      score: cosineSimilarity(
        queryEmbedding,
        document.embedding,
      ),
    }))
    .sort(
      (a, b) =>
        b.score - a.score,
    )
    .slice(0, limit);
}

