export function getOutgoing(
  graph: CodeGraph,
  entityId: string,
  relationshipTypes?: RelationshipType[],
): GraphRelationship[] {
  const edges = graph.outgoing.get(entityId) ?? [];

  if (!relationshipTypes || relationshipTypes.length === 0) {
    return edges;
  }

  return edges.filter((edge) =>
    relationshipTypes.includes(edge.type),
  );
}

export function chunkFile(file: ParsedFile): CodeChunk[] {
  const chunks: CodeChunk[] = [];

  /*
   * Prefer semantic chunks such as functions and classes.
   * If no code structures were discovered, fall back to
   * creating a file-level chunk.
   */

  for (const fn of file.functions) {
    chunks.push(functionToChunk(file, fn));
  }

  for (const classInfo of file.classes) {
    chunks.push(classToChunk(file, classInfo));
  }

  if (chunks.length === 0 && file.content.trim().length > 0) {
    chunks.push(fileToChunk(file));
  }

  return chunks;
}

function normalizeId(value: string): string {
  return value
    .replace(/\\/g, "/")
    .replace(/[^a-zA-Z0-9/_-]/g, "-")
    .toLowerCase();
}

function extractFunctionCalls(
  functionContent: string,
): string[] {
  const calls = new Set<string>();

  const callPattern =
    /\b([A-Za-z_$][A-Za-z0-9_$]*)\s*\(/g;

  const ignoredCalls = new Set([
    "if",
    "for",
    "while",
    "switch",
    "catch",
    "function",
    "constructor",
    "console",
  ]);

  let match: RegExpExecArray | null;

  while (
    (match = callPattern.exec(functionContent)) !== null
  ) {
    const functionName = match[1];

    if (ignoredCalls.has(functionName)) {
      continue;
    }

    calls.add(functionName);
  }

  return Array.from(calls);
}

export function traverseGraph(
  graph: CodeGraph,
  startEntityId: string,
  options: TraverseOptions = {},
): TraversalResult[] {
  const maxDepth = options.maxDepth ?? 2;

  const visited = new Set<string>();
  const results: TraversalResult[] = [];

  const queue: Array<{
    entityId: string;
    depth: number;
    via?: GraphRelationship;
  }> = [
    {
      entityId: startEntityId,
      depth: 0,
    },
  ];

  while (queue.length > 0) {
    const current = queue.shift()!;

    if (visited.has(current.entityId)) {
      continue;
    }

    visited.add(current.entityId);

    const entity = graph.nodes.get(current.entityId);

    if (!entity) {
      continue;
    }

    results.push({
      entity,
      depth: current.depth,
      via: current.via,
    });

    if (current.depth >= maxDepth) {
      continue;
    }

    const outgoing = getOutgoing(
      graph,
      current.entityId,
      options.relationshipTypes,
    );

    const incoming = getIncoming(
      graph,
      current.entityId,
      options.relationshipTypes,
    );

    for (const edge of outgoing) {
      if (!visited.has(edge.targetId)) {
        queue.push({
          entityId: edge.targetId,
          depth: current.depth + 1,
          via: edge,
        });
      }
    }

    for (const edge of incoming) {
      if (!visited.has(edge.sourceId)) {
        queue.push({
          entityId: edge.sourceId,
          depth: current.depth + 1,
          via: edge,
        });
      }
    }
  }

  return results;
}

export function parseTypeScriptAST(
  content: string,
  filePath: string,
): ASTParseResult {
  const scriptTarget = ts.ScriptTarget.Latest;
  const sourceFile = ts.createSourceFile(
    filePath,
    content,
    scriptTarget,
    true, // setParentNodes
  );

  const imports: ParsedImport[] = [];
  const functions: ParsedFunction[] = [];
  const classes: ParsedClass[] = [];

  function getLineNumber(pos: number): number {
    return sourceFile.getLineAndCharacterOfPosition(pos).line + 1;
  }

  function getNodeContent(node: ts.Node): string {
    return node.getText(sourceFile);
  }

  function visit(node: ts.Node) {
    // 1. Imports
    if (ts.isImportDeclaration(node)) {
      const moduleSpecifier = (node.moduleSpecifier as ts.StringLiteral).text;
      const names: string[] = [];

      if (node.importClause) {
        if (node.importClause.name) {
          names.push(node.importClause.name.getText(sourceFile));
        }

        if (node.importClause.namedBindings) {
          if (ts.isNamedImports(node.importClause.namedBindings)) {
            for (const element of node.importClause.namedBindings.elements) {
              names.push(element.name.getText(sourceFile));
            }
          } else if (ts.isNamespaceImport(node.importClause.namedBindings)) {
            names.push(node.importClause.namedBindings.name.getText(sourceFile));
          }
        }
      }

      imports.push({
        source: moduleSpecifier,
        names,
        line: getLineNumber(node.getStart()),
      });
    }

    // 2. Function Declarations
    else if (ts.isFunctionDeclaration(node) && node.name) {
      const name = node.name.getText(sourceFile);
      const startLine = getLineNumber(node.getStart());
      const endLine = getLineNumber(node.getEnd());

      functions.push({
        name,
        startLine,
        endLine,
        content: getNodeContent(node),
      });
    }

    // 3. Arrow Function / Function Expression Variable Declarations
    else if (ts.isVariableDeclaration(node) && node.name && node.initializer) {
      if (
        ts.isArrowFunction(node.initializer) ||
        ts.isFunctionExpression(node.initializer)
      ) {
        const name = node.name.getText(sourceFile);
        const startLine = getLineNumber(node.getStart());
        const endLine = getLineNumber(node.getEnd());

        functions.push({
          name,
          startLine,
          endLine,
          content: getNodeContent(node.parent?.parent ?? node),
        });
      }
    }

    // 4. Class Declarations & Methods
    else if (ts.isClassDeclaration(node) && node.name) {
      const className = node.name.getText(sourceFile);
      const classStartLine = getLineNumber(node.getStart());
      const classEndLine = getLineNumber(node.getEnd());

      classes.push({
        name: className,
        startLine: classStartLine,
        endLine: classEndLine,
        content: getNodeContent(node),
      });

      // Extract class methods as functions
      for (const member of node.members) {
        if (ts.isMethodDeclaration(member) && member.name) {
          const methodName = member.name.getText(sourceFile);
          const methodStartLine = getLineNumber(member.getStart());
          const methodEndLine = getLineNumber(member.getEnd());

          functions.push({
            name: `${className}.${methodName}`,
            startLine: methodStartLine,
            endLine: methodEndLine,
            content: getNodeContent(member),
          });
        }
      }
    }

    ts.forEachChild(node, visit);
  }

  visit(sourceFile);

  return {
    imports,
    functions,
    classes,
  };
}

function getLineNumber(pos: number): number {
    return sourceFile.getLineAndCharacterOfPosition(pos).line + 1;
  }

