export function isPathWithinRoot(
  filePath: string,
  rootDirectory: string,
): boolean {
  const resolvedRoot = path.resolve(rootDirectory);
  const resolvedFile = path.resolve(filePath);

  return (
    resolvedFile.startsWith(resolvedRoot) &&
    resolvedFile !== resolvedRoot
  );
}

export async function hybridSearch(
  query: string,
  graph: CodeGraph,
  chunks: CodeChunk[],
  vectorResults: VectorSearchResult[],
  options: HybridSearchOptions = {},
): Promise<HybridSearchResult[]> {
  const limit =
    options.limit ?? 10;

  const graphLimit =
    options.graphLimit ?? 15;

  const vectorWeight =
    options.vectorWeight ?? 0.6;

  const graphWeight =
    options.graphWeight ?? 0.4;

  const graphResults =
    graphSearch(
      graph,
      query,
      {
        limit: graphLimit,
        maxDepth:
          options.graphMaxDepth ?? 2,
      },
    );

  const normalizedVectorScores =
    normalizeVectorScores(
      vectorResults,
    );

  const resultMap =
    new Map<
      string,
      HybridSearchResult
    >();

  /*
   * Add vector results first.
   */
  for (const result of vectorResults) {
    const normalizedVectorScore =
      normalizedVectorScores.get(
        result.chunk.id,
      ) ?? 0;

    resultMap.set(
      result.chunk.id,
      {
        chunk: result.chunk,

        name:
          result.chunk.name ??
          result.chunk.filePath,

        filePath:
          result.chunk.filePath,

        vectorScore:
          normalizedVectorScore,

        graphScore: 0,

        hybridScore:
          normalizedVectorScore *
          vectorWeight,

        sources: ["vector"],
      },
    );
  }

  /*
   * Merge GraphRAG results.
   */
  for (const graphResult of graphResults) {
    const matchingChunk =
      findChunkForGraphEntity(
        chunks,
        graphResult.entity.filePath,
        graphResult.entity.name,
      );

    /*
     * Functions/classes usually map
     * directly to chunks.
     *
     * File/module graph nodes may not.
     */
    const key =
      matchingChunk?.id ??
      graphResult.entity.id;

    const existing =
      matchingChunk
        ? resultMap.get(
            matchingChunk.id,
          )
        : resultMap.get(key);

    if (existing) {
      existing.graphScore =
        Math.max(
          existing.graphScore,
          graphResult.score,
        );

      existing.hybridScore =
        existing.vectorScore *
          vectorWeight +
        existing.graphScore *
          graphWeight;

      if (
        !existing.sources.includes(
          "graph",
        )
      ) {
        existing.sources.push(
          "graph",
        );
      }

      existing.graphDepth =
        graphResult.depth;

      existing.graphMatchType =
        graphResult.matchType;

      continue;
    }

    resultMap.set(
      key,
      {
        chunk:
          matchingChunk,

        name:
          graphResult.entity.name,

        filePath:
          graphResult.entity.filePath,

        vectorScore: 0,

        graphScore:
          graphResult.score,

        hybridScore:
          graphResult.score *
          graphWeight,

        sources: ["graph"],

        graphDepth:
          graphResult.depth,

        graphMatchType:
          graphResult.matchType,
      },
    );
  }

  return Array.from(
    resultMap.values(),
  )
    .sort(
      (a, b) =>
        b.hybridScore -
        a.hybridScore,
    )
    .slice(0, limit);
}

function normalizeVectorScores(
  results: VectorSearchResult[],
): Map<string, number> {
  const normalized =
    new Map<string, number>();

  if (results.length === 0) {
    return normalized;
  }

  const scores =
    results.map(
      (result) => result.score,
    );

  const max =
    Math.max(...scores);

  const min =
    Math.min(...scores);

  const range =
    max - min;

  for (const result of results) {
    let score = 1;

    if (range > 0) {
      score =
        (result.score - min) /
        range;
    }

    normalized.set(
      result.chunk.id,
      score,
    );
  }

  return normalized;
}

function findChunkForGraphEntity(
  chunks: CodeChunk[],
  filePath: string | undefined,
  name: string,
): CodeChunk | undefined {
  if (!filePath) {
    return undefined;
  }

  return chunks.find(
    (chunk) =>
      chunk.filePath === filePath &&
      chunk.name === name,
  );
}

export function getNeighbors(
  graph: CodeGraph,
  entityId: string,
  relationshipTypes?: RelationshipType[],
): GraphEntity[] {
  const neighborIds = new Set<string>();

  const outgoing = getOutgoing(
    graph,
    entityId,
    relationshipTypes,
  );

  const incoming = getIncoming(
    graph,
    entityId,
    relationshipTypes,
  );

  for (const edge of outgoing) {
    neighborIds.add(edge.targetId);
  }

  for (const edge of incoming) {
    neighborIds.add(edge.sourceId);
  }

  const neighbors: GraphEntity[] = [];

  for (const id of neighborIds) {
    const entity = graph.nodes.get(id);

    if (entity) {
      neighbors.push(entity);
    }
  }

  return neighbors;
}

export function isSecretFile(filename: string): boolean {
  const basename = path.basename(filename);
  return SECRET_PATTERNS.some((pattern) => pattern.test(basename));
}

export function isIgnoredDirectory(dirName: string): boolean {
  return IGNORED_DIRECTORIES.has(dirName);
}

export function isIgnoredFile(filename: string): boolean {
  const basename = path.basename(filename);
  if (IGNORED_FILES.has(basename)) {
    return true;
  }
  return isSecretFile(basename);
}

export function detectLanguage(filePath: string): SupportedLanguage {
  const extension = path.extname(filePath).toLowerCase();

  switch (extension) {
    case ".ts":
    case ".tsx":
      return "typescript";

    case ".js":
    case ".jsx":
    case ".mjs":
    case ".cjs":
      return "javascript";

    case ".py":
      return "python";

    case ".json":
      return "json";

    default:
      return "unknown";
  }
}

function findBlockEnd(lines: string[], startIndex: number): number {
  let braceDepth = 0;
  let started = false;

  for (let index = startIndex; index < lines.length; index++) {
    const line = lines[index];

    for (const character of line) {
      if (character === "{") {
        braceDepth++;
        started = true;
      }

      if (character === "}") {
        braceDepth--;
      }
    }

    if (started && braceDepth === 0) {
      return index;
    }
  }

  return startIndex;
}

export async function withTransaction<T>(
  callback: (client: PoolClient) => Promise<T>,
): Promise<T> {
  const client = await pool.connect();

  try {
    await client.query("BEGIN");
    const result = await callback(client);
    await client.query("COMMIT");
    return result;
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }
}

function createCallRelationships(
  file: ParsedFile,
  entities: GraphEntity[],
): GraphRelationship[] {
  const relationships: GraphRelationship[] = [];

  const functionEntities = entities.filter(
    (entity) => entity.type === "function",
  );

  for (const fn of file.functions) {
    const caller = functionEntities.find(
      (entity) =>
        entity.filePath === file.filePath &&
        entity.name === fn.name &&
        entity.startLine === fn.startLine,
    );

    if (!caller) {
      continue;
    }

    const calledFunctionNames =
      extractFunctionCalls(fn.content);

    for (const calledName of calledFunctionNames) {
      if (calledName === fn.name) {
        continue;
      }

      /*
       * Priority 1:
       * Resolve functions in the same file.
       */
      const sameFileTarget =
        functionEntities.find(
          (entity) =>
            entity.filePath === file.filePath &&
            entity.name === calledName,
        );

      if (sameFileTarget) {
        relationships.push({
          id: createRelationshipId(
            caller.id,
            "calls",
            sameFileTarget.id,
          ),

          type: "calls",

          sourceId: caller.id,
          targetId: sameFileTarget.id,

          metadata: {
            caller: fn.name,
            callee: calledName,
            resolution: "same-file",
          },
        });

        continue;
      }

      /*
       * Priority 2:
       * Resolve imported named functions.
       */
      const importedFunctionNames =
        file.imports.flatMap(
          (importInfo) => importInfo.names,
        );

      if (
        !importedFunctionNames.includes(
          calledName,
        )
      ) {
        continue;
      }

      const possibleImportedTargets =
        functionEntities.filter(
          (entity) =>
            entity.name === calledName,
        );

      /*
       * Only create an edge when the target
       * is unambiguous.
       */
      if (
        possibleImportedTargets.length === 1
      ) {
        const target =
          possibleImportedTargets[0];

        relationships.push({
          id: createRelationshipId(
            caller.id,
            "calls",
            target.id,
          ),

          type: "calls",

          sourceId: caller.id,
          targetId: target.id,

          metadata: {
            caller: fn.name,
            callee: calledName,
            resolution: "imported-name",
          },
        });
      }
    }
  }

  return relationships;
}

