function extractImports(
  lines: string[],
  language: SupportedLanguage,
): ParsedImport[] {
  const imports: ParsedImport[] = [];

  if (language === "typescript" || language === "javascript") {
    lines.forEach((line, index) => {
      const trimmed = line.trim();

      const fromMatch = trimmed.match(
        /^import\s+(.+?)\s+from\s+["'](.+?)["']/,
      );

      if (fromMatch) {
        const rawNames = fromMatch[1];
        const source = fromMatch[2];

        const names = rawNames
          .replace(/[{}]/g, "")
          .split(",")
          .map((name) => name.trim())
          .filter(Boolean);

        imports.push({
          source,
          names,
          line: index + 1,
        });

        return;
      }

      const sideEffectMatch = trimmed.match(/^import\s+["'](.+?)["']/);

      if (sideEffectMatch) {
        imports.push({
          source: sideEffectMatch[1],
          names: [],
          line: index + 1,
        });
      }
    });
  }

  if (language === "python") {
    lines.forEach((line, index) => {
      const trimmed = line.trim();

      const fromMatch = trimmed.match(
        /^from\s+([\w.]+)\s+import\s+(.+)$/,
      );

      if (fromMatch) {
        imports.push({
          source: fromMatch[1],
          names: fromMatch[2]
            .split(",")
            .map((name) => name.trim())
            .filter(Boolean),
          line: index + 1,
        });

        return;
      }

      const importMatch = trimmed.match(/^import\s+(.+)$/);

      if (importMatch) {
        const modules = importMatch[1]
          .split(",")
          .map((name) => name.trim())
          .filter(Boolean);

        for (const moduleName of modules) {
          imports.push({
            source: moduleName,
            names: [],
            line: index + 1,
          });
        }
      }
    });
  }

  return imports;
}

function extractJavaScriptFunctions(lines: string[]): ParsedFunction[] {
  const functions: ParsedFunction[] = [];

  const patterns = [
    /^(?:export\s+)?(?:async\s+)?function\s+([A-Za-z_$][\w$]*)/,
    /^(?:export\s+)?const\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s*)?\(/,
    /^(?:export\s+)?const\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s*)?[A-Za-z_$][\w$]*\s*=>/,
  ];

  for (let index = 0; index < lines.length; index++) {
    const trimmed = lines[index].trim();

    for (const pattern of patterns) {
      const match = trimmed.match(pattern);

      if (!match) {
        continue;
      }

      const endIndex = findBlockEnd(lines, index);

      functions.push({
        name: match[1],
        startLine: index + 1,
        endLine: endIndex + 1,
        content: lines.slice(index, endIndex + 1).join("\n"),
      });

      break;
    }
  }

  return functions;
}

function findFirstRelevantRank(
  returned: string[],
  expected: string[],
): number | null {
  for (
    let index = 0;
    index < returned.length;
    index++
  ) {
    if (
      expected.includes(
        returned[index],
      )
    ) {
      return index + 1;
    }
  }

  return null;
}

function calculateRecallAtK(
  returned: string[],
  expected: string[],
  k: number,
): number {
  const topK =
    returned.slice(0, k);

  const relevantFound =
    expected.filter(
      (name) =>
        topK.includes(name),
    );

  return (
    relevantFound.length /
    expected.length
  );
}

