function extractPythonFunctions(lines: string[]): ParsedFunction[] {
  const functions: ParsedFunction[] = [];

  for (let index = 0; index < lines.length; index++) {
    const line = lines[index];
    const match = line.match(/^(\s*)def\s+([A-Za-z_]\w*)\s*\(/);

    if (!match) {
      continue;
    }

    const indentation = match[1].length;
    let endIndex = index;

    for (let nextIndex = index + 1; nextIndex < lines.length; nextIndex++) {
      const nextLine = lines[nextIndex];

      if (nextLine.trim() === "") {
        endIndex = nextIndex;
        continue;
      }

      const nextIndentation = nextLine.match(/^\s*/)?.[0].length ?? 0;

      if (nextIndentation <= indentation) {
        break;
      }

      endIndex = nextIndex;
    }

    functions.push({
      name: match[2],
      startLine: index + 1,
      endLine: endIndex + 1,
      content: lines.slice(index, endIndex + 1).join("\n"),
    });
  }

  return functions;
}

