export async function parseFile(filePath: string): Promise<ParsedFile> {
  const absolutePath = path.resolve(filePath);
  const content = await fs.readFile(absolutePath, "utf8");

  const language = detectLanguage(filePath);
  const lines = content.split(/\r?\n/);

  let imports: ParsedImport[] = [];
  let functions: ParsedFunction[] = [];
  let classes: ParsedClass[] = [];

  if (language === "typescript" || language === "javascript") {
    const astResult = parseTypeScriptAST(content, filePath);
    imports = astResult.imports;
    functions = astResult.functions;
    classes = astResult.classes;
  } else if (language === "python") {
    imports = extractImports(lines, language);
    functions = extractPythonFunctions(lines);
    classes = extractPythonClasses(lines);
  } else {
    imports = extractImports(lines, language);
  }

  return {
    filePath: path.normalize(filePath),
    language,
    content,
    imports,
    functions,
    classes,
  };
}

function normalizeName(
  name: string,
): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9_$]+/g, " ")
    .trim();
}

function splitIdentifier(name: string): string[] {
  return name
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2")
    .toLowerCase()
    .split(/[^a-z0-9_$]+/)
    .filter((t) => t.length > 1);
}

function calculateExactNameBonus(
  query: string,
  result: HybridSearchResult,
): number {
  const normalizedQuery =
    normalizeQuery(query);

  const normalizedName =
    normalizeName(result.name);

  if (!normalizedName) {
    return 0;
  }

  if (
    normalizedQuery === normalizedName
  ) {
    return 1;
  }

  if (
    normalizedQuery.includes(
      normalizedName,
    )
  ) {
    return 0.8;
  }

  const queryTokens = normalizedQuery
    .split(/\s+/)
    .filter(Boolean);

  const expandedQuery = new Set<string>(queryTokens);
  for (const q of queryTokens) {
    for (const exp of QUERY_EXPANSIONS[q] ?? []) {
      expandedQuery.add(exp);
    }
  }

  const nameParts = splitIdentifier(result.name);
  if (nameParts.length > 0) {
    let matchedParts = 0;
    for (const part of nameParts) {
      if (expandedQuery.has(part)) {
        matchedParts++;
      }
    }

    if (matchedParts === nameParts.length) {
      return 0.85;
    } else if (matchedParts > 0) {
      return 0.4 * (matchedParts / nameParts.length);
    }
  }

  return 0;
}

function calculateAgreementBonus(
  result: HybridSearchResult,
): number {
  const hasVector =
    result.sources.includes("vector");

  const hasGraph =
    result.sources.includes("graph");

  return hasVector && hasGraph
    ? 1
    : 0;
}

function calculateDepthBonus(
  result: HybridSearchResult,
): number {
  if (
    result.graphDepth === undefined
  ) {
    return 0;
  }

  if (result.graphDepth === 0) {
    return 1;
  }

  if (result.graphDepth === 1) {
    return 0.7;
  }

  if (result.graphDepth === 2) {
    return 0.4;
  }

  return 0.1;
}

function calculateTypeBonus(
  result: HybridSearchResult,
): number {
  const type =
    result.chunk?.type;

  if (
    type === "function" ||
    type === "class"
  ) {
    return 1;
  }

  if (type === "file") {
    return 0.4;
  }

  return 0;
}

export async function scanRepository(
  rootDirectory: string,
): Promise<string[]> {
  const resolvedRoot = path.resolve(rootDirectory);
  const files: string[] = [];

  async function walk(directory: string): Promise<void> {
    if (!isPathWithinRoot(directory, resolvedRoot) && directory !== resolvedRoot) {
      console.warn(`🛡 Security: Blocked path traversal walk outside root: ${directory}`);
      return;
    }

    const entries = await fs.readdir(directory, {
      withFileTypes: true,
    });

    for (const entry of entries) {
      const fullPath = path.join(directory, entry.name);
      const resolvedPath = path.resolve(fullPath);

      if (!isPathWithinRoot(resolvedPath, resolvedRoot)) {
        console.warn(`🛡 Security: Blocked out-of-root file: ${resolvedPath}`);
        continue;
      }

      if (entry.isDirectory()) {
        if (isIgnoredDirectory(entry.name)) {
          continue;
        }

        await walk(fullPath);
        continue;
      }

      if (!entry.isFile()) {
        continue;
      }

      if (isIgnoredFile(entry.name)) {
        console.log(`🛡 Security: Filtered secret/artifact file: ${entry.name}`);
        continue;
      }

      try {
        const stat = await fs.stat(fullPath);
        if (stat.size > MAX_FILE_SIZE_BYTES) {
          console.warn(
            `🛡 Security: Skipped oversized file (${(stat.size / 1024 / 1024).toFixed(2)} MB): ${fullPath}`,
          );
          continue;
        }
      } catch {
        continue;
      }

      const extension = path.extname(entry.name).toLowerCase();

      if (SUPPORTED_EXTENSIONS.has(extension)) {
        files.push(fullPath);
      }
    }
  }

  await walk(resolvedRoot);

  return files.sort();
}

