function createClassEntity(
  file: ParsedFile,
  classInfo: ParsedClass,
): GraphEntity {
  return {
    id: `class:${normalizeId(file.filePath)}:${normalizeId(classInfo.name)}:${classInfo.startLine}`,

    type: "class",

    name: classInfo.name,

    filePath: file.filePath,

    startLine: classInfo.startLine,
    endLine: classInfo.endLine,

    language: file.language,

    metadata: {
      parentFile: file.filePath,
    },
  };
}

function findFirstRelevantRank(
  returned: string[],
  expected: string[],
): number | null {
  for (let index = 0; index < returned.length; index++) {
    if (expected.includes(returned[index])) {
      return index + 1;
    }
  }
  return null;
}

