export async function parseRepository(
  rootDirectory: string,
): Promise<ParsedFile[]> {
  const files = await scanRepository(rootDirectory);

  const parsedFiles: ParsedFile[] = [];

  for (const file of files) {
    parsedFiles.push(await parseFile(file));
  }

  return parsedFiles;
}

