export function rerankResults(
  query: string,
  results: HybridSearchResult[],
  options: RerankOptions = {},
): RerankedResult[] {
  const limit =
    options.limit ??
    results.length;

  return results
    .map((result) => {
      const exactNameBonus =
        calculateExactNameBonus(
          query,
          result,
        );

      const agreementBonus =
        calculateAgreementBonus(
          result,
        );

      const depthBonus =
        calculateDepthBonus(
          result,
        );

      const typeBonus =
        calculateTypeBonus(
          result,
        );

      const hybridBase =
        result.hybridScore;

      const rerankScore =
        hybridBase * 0.50 +
        exactNameBonus * 0.25 +
        agreementBonus * 0.10 +
        depthBonus * 0.10 +
        typeBonus * 0.05;

      return {
        ...result,

        rerankScore,

        rerankSignals: {
          hybridBase,
          exactNameBonus,
          agreementBonus,
          depthBonus,
          typeBonus,
        },
      };
    })
    .sort(
      (a, b) =>
        b.rerankScore -
        a.rerankScore,
    )
    .slice(0, limit);
}

