export async function runMigrations(
  migrationsDir = path.resolve(process.cwd(), "migrations"),
): Promise<void> {
  console.log("📦 Checking PostgreSQL database migrations...");

  // 1. Ensure migrations tracking table exists
  await query(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      version INTEGER PRIMARY KEY,
      name TEXT NOT NULL,
      applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    );
  `);

  // 2. Fetch applied migrations
  const appliedResult = await query<MigrationRecord>(
    `SELECT version, name, applied_at FROM schema_migrations ORDER BY version ASC`,
  );
  const appliedVersions = new Set(appliedResult.rows.map((row) => row.version));

  // 3. Read migration files
  let files: string[] = [];
  try {
    const entries = await fs.readdir(migrationsDir);
    files = entries.filter((f) => f.endsWith(".sql")).sort();
  } catch (err) {
    console.warn(`⚠️ Migrations directory not found at: ${migrationsDir}`);
    return;
  }

  let appliedCount = 0;

  for (const file of files) {
    const match = file.match(/^(\d+)_/);
    if (!match) {
      continue;
    }

    const version = Number.parseInt(match[1], 10);
    if (appliedVersions.has(version)) {
      continue;
    }

    console.log(`🚀 Applying migration ${file}...`);
    const filePath = path.join(migrationsDir, file);
    const sql = await fs.readFile(filePath, "utf8");

    await withTransaction(async (client) => {
      await client.query(sql);
      await client.query(
        `INSERT INTO schema_migrations (version, name) VALUES ($1, $2)`,
        [version, file],
      );
    });

    console.log(`✓ Migration ${file} applied successfully.`);
    appliedCount++;
  }

  if (appliedCount === 0) {
    console.log("✓ Database schema is up to date (no pending migrations).");
  } else {
    console.log(`✓ Applied ${appliedCount} new migration(s).`);
  }
}

export async function query<T extends QueryResultRow = QueryResultRow>(
  text: string,
  params: unknown[] = [],
): Promise<QueryResult<T>> {
  return pool.query<T>(text, params);
}

export async function queryWithRetry<T extends QueryResultRow = QueryResultRow>(
  text: string,
  params: unknown[] = [],
  maxRetries = 3,
  delayMs = 200,
): Promise<QueryResult<T>> {
  let attempt = 0;

  while (true) {
    try {
      return await pool.query<T>(text, params);
    } catch (error: any) {
      attempt++;
      const isTransient =
        error?.code === "ECONNRESET" ||
        error?.code === "ETIMEDOUT" ||
        error?.code === "57P01" ||
        error?.message?.includes("timeout");

      if (isTransient && attempt < maxRetries) {
        console.warn(
          `⚠️ Temporary DB error (${error.message}). Retrying (${attempt}/${maxRetries}) in ${delayMs}ms...`,
        );
        await new Promise((res) => setTimeout(res, delayMs * attempt));
        continue;
      }
      throw error;
    }
  }
}

export function validateTopK(limit?: number): number {
  if (limit === undefined || limit === null) {
    return LIMITS.defaultResults;
  }

  if (typeof limit !== "number" || Number.isNaN(limit) || !Number.isFinite(limit)) {
    throw new ResourceLimitError("Limit must be a valid finite number.");
  }

  if (limit <= 0) {
    throw new ResourceLimitError("Limit must be a positive integer greater than 0.");
  }

  if (limit > LIMITS.maxResults) {
    throw new ResourceLimitError(
      `Requested limit (${limit}) exceeds maximum result limit of ${LIMITS.maxResults}.`,
    );
  }

  return Math.floor(limit);
}

export function validateChunkContentSize(content: string): string {
  const bytes = Buffer.byteLength(content, "utf8");
  if (bytes > LIMITS.maxChunkSizeBytes) {
    console.warn(
      `⚠️ Truncated chunk content exceeding ${LIMITS.maxChunkSizeBytes} bytes (original: ${bytes} bytes)`,
    );
    return content.slice(0, LIMITS.maxChunkSizeBytes);
  }
  return content;
}

export function validateRepositoryScan(fileCount: number, totalSizeBytes: number): void {
  if (fileCount > LIMITS.maxRepositoryFiles) {
    throw new ResourceLimitError(
      `Repository file count (${fileCount}) exceeds limit of ${LIMITS.maxRepositoryFiles} files.`,
    );
  }

  if (totalSizeBytes > LIMITS.maxRepositorySizeBytes) {
    throw new ResourceLimitError(
      `Repository total size (${(totalSizeBytes / 1024 / 1024).toFixed(1)} MB) exceeds limit of ${LIMITS.maxRepositorySizeBytes / 1024 / 1024} MB.`,
    );
  }
}

export function validateRepositoryChunkCount(totalChunks: number): void {
  if (totalChunks > LIMITS.maxRepositoryChunks) {
    throw new ResourceLimitError(
      `Repository chunk count (${totalChunks}) exceeds limit of ${LIMITS.maxRepositoryChunks} chunks.`,
    );
  }
}

export function validateGraphDepth(depth?: number): number {
  if (depth === undefined || depth === null) {
    return LIMITS.maxGraphDepth;
  }

  if (typeof depth !== "number" || Number.isNaN(depth) || depth <= 0) {
    return LIMITS.maxGraphDepth;
  }

  return Math.min(Math.floor(depth), LIMITS.maxGraphDepth);
}

