public async indexSingleFile(filePath: string): Promise<IncrementalIndexStats> {
    const absolutePath = path.resolve(filePath);

    // Security & exclusion checks
    if (!isPathWithinRoot(absolutePath, this.rootDirectory) && absolutePath !== this.rootDirectory) {
      return { file: filePath, action: "skipped", chunksCount: 0, reason: "Out of root boundary" };
    }

    const basename = path.basename(absolutePath);
    if (isIgnoredFile(basename)) {
      return { file: filePath, action: "skipped", chunksCount: 0, reason: "Secret or ignored file" };
    }

    // Check if file exists (if deleted, trigger deletion)
    let exists = false;
    try {
      const stat = await fs.stat(absolutePath);
      exists = true;

      if (stat.size > MAX_FILE_SIZE_BYTES) {
        return { file: filePath, action: "skipped", chunksCount: 0, reason: "File exceeds 1 MB limit" };
      }
    } catch {
      exists = false;
    }

    if (!exists) {
      return this.deleteFileFromIndex(absolutePath);
    }

    // Parse & Chunk single file
    const parsedFile = await parseFile(absolutePath);
    const chunks: CodeChunk[] = chunkFile(parsedFile);

    if (chunks.length === 0) {
      return { file: filePath, action: "skipped", chunksCount: 0, reason: "No indexable content" };
    }

    // Upsert chunks into PostgreSQL + pgvector
    await upsertChunks(this.repositoryName, chunks);

    console.log(`⚡ Auto-Indexed changed file: ${path.basename(filePath)} (${chunks.length} chunks)`);
    return { file: filePath, action: "indexed", chunksCount: chunks.length };
  }

public async deleteFileFromIndex(filePath: string): Promise<IncrementalIndexStats> {
    const normalizedPath = path.normalize(filePath);
    const result = await query(
      `DELETE FROM code_chunks WHERE repository = $1 AND file_path = $2`,
      [this.repositoryName, normalizedPath],
    );

    const deletedChunks = result.rowCount ?? 0;
    if (deletedChunks > 0) {
      console.log(`🧹 Auto-Cleaned deleted file from DB: ${path.basename(filePath)} (${deletedChunks} chunks deleted)`);
    }

    return { file: filePath, action: "deleted", chunksCount: deletedChunks };
  }

public watchRepository(
    onChange?: (stats: IncrementalIndexStats) => void,
    debounceMs = 300,
  ): void {
    if (this.watcher) {
      return;
    }

    console.log(`👁 Starting automatic file watcher on ${this.rootDirectory}...`);

    this.watcher = fsSync.watch(
      this.rootDirectory,
      { recursive: true },
      (eventType, filename) => {
        if (!filename) {
          return;
        }

        const fullPath = path.join(this.rootDirectory, filename);
        const parts = filename.split(path.sep);

        if (parts.some((part) => isIgnoredDirectory(part) || isIgnoredFile(part))) {
          return;
        }

        // Debounce frequent rapid file edits
        if (this.debounceMap.has(fullPath)) {
          clearTimeout(this.debounceMap.get(fullPath));
        }

        const timer = setTimeout(async () => {
          this.debounceMap.delete(fullPath);
          try {
            const stats = await this.indexSingleFile(fullPath);
            if (onChange) {
              onChange(stats);
            }
          } catch (err) {
            console.error(`❌ Error auto-indexing ${filename}:`, err);
          }
        }, debounceMs);

        this.debounceMap.set(fullPath, timer);
      },
    );
  }

public stopWatching(): void {
    if (this.watcher) {
      this.watcher.close();
      this.watcher = null;
      console.log("🛑 Automatic file watcher stopped.");
    }
  }

